// A plain-JavaScript package entry, the ordinary case: prepare bundles it into one
// artifact module and the isolate imports that instead of walking node_modules.
import { titleCase } from "./internal/title-case.js";

export function slugLabel(slug) {
  return slug.split("-").map(titleCase).join(" ");
}

// Never imported. A package's whole export surface is not the project's business, and
// bundling for the names actually asked for is what keeps `Bun.build` honest — see
// `bundlePackage` in packages/pletivo/src/prepare/vendor.ts.
export function unusedHelper(text) {
  return text.trim();
}
